check:
set -eu
probe=tests/aep_studio_empty_argv_contract.rs
test ! -e "$probe"
trap 'unlink "$probe"' EXIT
cat > "$probe" <<'RUST'
use aep::task::{Check, TaskManifest};

fn manifest(check: &[&str]) -> TaskManifest {
    TaskManifest {
        title: None,
        allowed_paths: vec!["src/task.rs".into()],
        check: check.iter().map(|item| (*item).into()).collect(),
        criteria: vec!["AC-1".into()],
        checks: vec![],
    }
}

#[test]
fn accepts_empty_arguments_but_not_an_empty_program_or_nul() {
    let argv = ["sh", "-ec", "test \"$#\" = 1 && test -z \"$1\"", "probe", ""];
    let mut primary = manifest(&argv);
    assert!(primary.validate().is_ok(), "primary rejected a deliberate empty argument");
    assert!(std::process::Command::new(&primary.check[0]).args(&primary.check[1..]).status().unwrap().success());
    for invalid in [vec![], vec!["", "value"], vec!["sh", "a\0b"]] {
        assert!(manifest(&invalid).validate().is_err());
    }
    let mut secondary = manifest(&["true"]);
    secondary.checks.push(Check {
        id: "secondary".into(),
        criteria: vec!["AC-2".into()],
        command: primary.check.split_off(0),
    });
    assert!(secondary.validate().is_ok(), "additional check rejected a deliberate empty argument");
    secondary.checks[0].command[4] = "bad\0arg".into();
    assert!(secondary.validate().is_err());
    secondary.checks[0].command = vec!["".into(), "value".into()];
    assert!(secondary.validate().is_err());
    secondary.checks[0].command.clear();
    assert!(secondary.validate().is_err());
}
RUST
if test -f /etc/aep-pilot-container; then sleep 10; fi
cargo test --quiet --locked --no-default-features --test aep_studio_empty_argv_contract
